def caesar_cipher(text: str, shift: int) -> str:
    result = ''
    for char in text:
        if char.isalpha():
            base = ord('a') + (1 if char.isupper() else 0)
            result += chr((ord(char) - base + shift + 26) % 26 + base)
        else:
            result += char
    return result
