```def caesar_cipher(text: str, shift: int) -> str:
    result = []
    for char in text:
        if char.isalpha():
            base = ord('A') if char.isupper() else ord('a')
            index = (ord(char) - base + shift) % 26
            result.append(chr((index + base) % 26 + ord('A')))
        else:
            result.append(char)
    return ''.join(result)
